WITH items(kind,name,x1,x2,x3,x4,definition) AS (SELECT 'schema',name,NULL,NULL,NULL,NULL,sql FROM sqlite_schema WHERE type='table' AND name IN ('t1','t2','t3','t4') UNION ALL SELECT 'data','t1',a,b,c,d,NULL FROM t1 UNION ALL SELECT 'data','t2',c,d,e,f,NULL FROM t2 UNION ALL SELECT 'data','t3',a,b,e,f,NULL FROM t3 UNION ALL SELECT 'data','t4',a,c,d,f,NULL FROM t4) SELECT kind,name,x1,x2,x3,x4,definition FROM items ORDER BY kind,name,x1 NULLS FIRST,x2 NULLS FIRST,x3 NULLS FIRST,x4 NULLS FIRST,definition NULLS FIRST;